import java.applet.*;import java.awt.*;import java.awt.image.*;public class Image_Prototype extends Applet{	Image robot_image;	Image background_image;		public void init(){			robot_image = getImage(getDocumentBase(), "bot1.GIF");		background_image = getImage(getDocumentBase(), "space.GIF");						setVisible(true);		}	public void start(){			Graphics page = getGraphics();		int x = 1, y = 1;		for(double counter = 0; counter<100000; counter++){						page.drawImage(background_image, 1, 1, this);			page.drawImage(background_image, 150, 1, this);			page.drawImage(background_image, 1, 150, this);			page.drawImage(background_image, 150, 150, this);			for(double index = 1; index<100000; index++){}				while(x < 300){				x++;				y++;				page.drawImage(robot_image, x, y, this);				page.drawImage(background_image, x, y, this);				for(double index = 1; index<100000; index++){}			}			x = 0;			y = 0;		}		}}